 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Eliminate isolated noise, while preserve colored shapes/components.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg:
                continue
            v = grid[r][c]
            neighbors = sum(grid[rr][cc] == v
                            for rr in range(max(0, r-1), min(h, r+2))
                            for cc in range(max(0, c-1), min(w, c+2))
                            if (rr, cc) != (r, c))
            if neighbors == 0:
                out[r][c] = bg
    # Any compact, near-rectangular component is an object with contaminant
    # pixels punched into it; restore its full bounding rectangle.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            pts = []
            while stack:
                y, x = stack.pop()
                pts.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in pts); r1=max(y for y,x in pts)
            c0=min(x for y,x in pts); c1=max(x for y,x in pts)
            area=(r1-r0+1)*(c1-c0+1)
            if len(pts) >= 3 and len(pts)/area >= 0.55:
                for y in range(r0,r1+1):
                    for x in range(c0,c1+1):
                        out[y][x] = color
    return out
